import numpy as np
import math

def f(x):
    return np.exp(x)

def nth_derivative(x, n):
    return np.exp(x)

def taylor_exp(x, n, a=0):
    result = 0.0
    for i in range(n + 1):
        term = nth_derivative(a, i) / math.factorial(i) * (x - a)**i
        result += term
    return result

x_val = 1.0
true_val = np.exp(x_val)

degrees = [1, 2, 3, 5, 10]
approximations = {}
errors = {}
for n in degrees:
    approx = taylor_exp(x_val, n)
    approximations[n] = approx
    errors[n] = abs(true_val - approx)

def taylor_sin(x, n):
    result = 0.0
    for i in range(n + 1):
        k = i
        term = ((-1)**k) * x**(2*k + 1) / math.factorial(2*k + 1)
        result += term
    return result

sin_true = np.sin(np.pi / 4)
sin_approx = taylor_sin(np.pi / 4, 5)

print(f"e^1 = {true_val:.6f}")
for n in degrees:
    print(f"Taylor degree {n}: {approximations[n]:.6f}, error: {errors[n]:.2e}")
print(f"sin(pi/4) = {sin_true:.6f}")
print(f"Taylor sin(pi/4) = {sin_approx:.6f}")
